changeSet.sql:
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_status_check;
ALTER TABLE users ADD CONSTRAINT users_status_check CHECK (status IN ('ACTIVE','INACTIVE','SUSPENDED','PENDING','TERMINATED'));
ALTER TABLE otp_records ADD COLUMN IF NOT EXISTS failed_attempts INTEGER NOT NULL DEFAULT 0;
CREATE TABLE login_security_records (
 id UUID PRIMARY KEY, user_id UUID, email VARCHAR(255) NOT NULL,
 kind VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL, reason VARCHAR(500), actor_id VARCHAR(255),
 ip_address VARCHAR(255), user_agent VARCHAR(500), device_id VARCHAR(255), token_hash VARCHAR(255),
 expires_at TIMESTAMP, created_at TIMESTAMP NOT NULL
);
CREATE INDEX idx_security_email_created ON login_security_records(email,created_at);
CREATE INDEX idx_security_kind_created ON login_security_records(kind,created_at);
CREATE INDEX idx_security_token_hash ON login_security_records(token_hash);
